const __pageData = JSON.parse('{"title":"Решение проблем","description":"Что проверить при пустой выдаче SymbolTrail, устаревших связях, ошибке MCP-подключения или отсутствии векторного поиска.","frontmatter":{"title":"Решение проблем","description":"Что проверить при пустой выдаче SymbolTrail, устаревших связях, ошибке MCP-подключения или отсутствии векторного поиска.","section":"Помощь"},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md"}');
